package httpserver

const recoveryPage = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Account recovery</title><h1>Account recovery</h1><form><label id="password">New password <input type="password" autocomplete="new-password" minlength="8" maxlength="72"></label><button id="submit" type="submit">Continue</button></form><output aria-live="polite"></output><script>const p=new URLSearchParams(location.hash.slice(1));const token=p.get('token');const reset=p.get('action')==='reset-password';history.replaceState(null,'',location.pathname);document.querySelector('#password').hidden=!reset;document.querySelector('#submit').textContent=reset?'Reset password':'Verify email';document.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#submit');button.disabled=true;try{const r=await fetch(reset?'/api/auth/reset-password':'/api/auth/verify-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,newPassword:reset?document.querySelector('input').value:''})});document.querySelector('output').textContent=r.ok?'Completed. You can now sign in.':'Unable to complete. Request a new link or try again later.';}catch{document.querySelector('output').textContent='Connection failed. Try again.';}finally{button.disabled=false;}};</script></html>`
